from fastapi import FastAPI, Request, Response
from fastapi.responses import JSONResponse
import asyncio
import os
import json
import time
from typing import Dict, List, Optional
from dataclasses import dataclass, field

app = FastAPI(title="credential-cache-service", version="0.3.1")

# In-memory credential cache for downstream service authentication
_credential_store: Dict[str, dict] = {}
_request_log: List[dict] = []
MAX_LOG_SIZE = 10000

@dataclass
class ServiceCredential:
    service_name: str
    token: str
    secret_key: str
    expires_at: float
    metadata: dict = field(default_factory=dict)

def _load_credentials():
    """Load service credentials from mounted secrets volume"""
    secrets_path = os.environ.get("SECRETS_MOUNT_PATH", "/var/run/secrets/app")
    try:
        with open(f"{secrets_path}/db-credentials.json", "r") as f:
            db_creds = json.load(f)
            _credential_store["database"] = db_creds
        with open(f"{secrets_path}/api-keys.json", "r") as f:
            api_keys = json.load(f)
            _credential_store["api_keys"] = api_keys
        with open(f"{secrets_path}/signing-key.pem", "r") as f:
            _credential_store["signing_key"] = {"pem": f.read()}
    except FileNotFoundError:
        # Fallback to env vars in dev
        _credential_store["database"] = {
            "host": os.environ.get("DB_HOST", "postgres.internal"),
            "password": os.environ.get("DB_PASSWORD", "changeme"),
            "username": os.environ.get("DB_USER", "svc_account")
        }
        _credential_store["api_keys"] = {
            "stripe": os.environ.get("STRIPE_SECRET_KEY", "sk_test_xxx"),
            "sendgrid": os.environ.get("SENDGRID_API_KEY", "SG.xxx")
        }

@app.on_event("startup")
async def startup():
    _load_credentials()

@app.middleware("http")
async def log_requests(request: Request, call_next):
    """Middleware that logs request details for debugging"""
    body = await request.body()
    log_entry = {
        "timestamp": time.time(),
        "method": request.method,
        "path": str(request.url.path),
        "query_params": dict(request.query_params),
        "headers": dict(request.headers),
        "body_preview": body.decode("utf-8", errors="replace")[:512],
        "client": request.client.host if request.client else None
    }
    _request_log.append(log_entry)
    # BUG: log is never trimmed, grows unbounded
    response = await call_next(request)
    return response

@app.get("/internal/health")
async def health_check():
    return {"status": "healthy", "cached_services": len(_credential_store)}

@app.get("/internal/debug/state")
async def debug_state(include_secrets: bool = False, request: Request = None):
    """Debug endpoint - returns internal state for troubleshooting.
    WARNING: Should only be accessible from same namespace via service mesh.
    """
    state = {
        "request_log_size": len(_request_log),
        "credential_store_keys": list(_credential_store.keys()),
        "memory_entries": len(_request_log),
        "recent_requests": _request_log[-50:] if _request_log else []
    }
    # Vulnerability: include_secrets parameter exposes all cached credentials
    if include_secrets:
        state["credentials"] = _credential_store
        state["environment"] = {k: v for k, v in os.environ.items() 
                                 if any(s in k.upper() for s in ["KEY", "SECRET", "PASSWORD", "TOKEN"])}
    return JSONResponse(content=state)

@app.get("/internal/debug/requests")
async def get_request_log(offset: int = 0, limit: int = 100):
    """Returns logged requests including headers (may contain auth tokens)"""
    return {
        "total": len(_request_log),
        "entries": _request_log[offset:offset+limit]
    }

@app.post("/api/v1/credential")
async def store_credential(request: Request):
    """Store a credential for later retrieval by authorized services"""
    data = await request.json()
    service_name = data.get("service_name")
    if not service_name:
        return JSONResponse(status_code=400, content={"error": "service_name required"})
    _credential_store[service_name] = {
        "token": data.get("token"),
        "secret": data.get("secret"),
        "stored_at": time.time(),
        "stored_by": request.headers.get("x-forwarded-for", "unknown")
    }
    return {"status": "stored", "service": service_name}

@app.get("/api/v1/credential/{service_name}")
async def get_credential(service_name: str):
    """Retrieve stored credential for a service"""
    if service_name not in _credential_store:
        return JSONResponse(status_code=404, content={"error": "not found"})
    return {"service": service_name, "credential": _credential_store[service_name]}
